import{_ as e,o as r,c as h,a2 as t}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"第一章 总则","description":"","frontmatter":{"title":"第一章 总则","date":"2023-12-29T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"],"law_version":"2023修订（2023-12-29 公布，2024-07-01 施行）","v1_source":"blogs/CL/第一章：总则.md"},"headers":[],"relativePath":"blogs/CL/diyizhang：zongze.md","filePath":"blogs/CL/第一章：总则.md"}'),o={name:"blogs/CL/diyizhang：zongze.md"};function i(l,a,n,d,s,c){return r(),h("div",null,[...a[0]||(a[0]=[t('<h1 id="第一章-总则" tabindex="-1">第一章 总则 <a class="header-anchor" href="#第一章-总则" aria-label="Permalink to &quot;第一章 总则&quot;">​</a></h1><h3 id="第一条" tabindex="-1">第一条 <a class="header-anchor" href="#第一条" aria-label="Permalink to &quot;第一条&quot;">​</a></h3><p>一条为了规范公司的组织和行为，保护公司、股东、职工和债权人的合法权益，完善中国特色现代企业制度，弘扬企业家精神，维护社会经济秩序，促进社会主义市场经济的发展，根据宪法，制定本法。</p><h3 id="第二条" tabindex="-1">第二条 <a class="header-anchor" href="#第二条" aria-label="Permalink to &quot;第二条&quot;">​</a></h3><p>二条本法所称公司，是指依照本法在中华人民共和国境内设立的有限责任公司和股份有限公司。</p><h3 id="第三条" tabindex="-1">第三条 <a class="header-anchor" href="#第三条" aria-label="Permalink to &quot;第三条&quot;">​</a></h3><p>三条公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。 公司的合法权益受法律保护，不受侵犯。</p><h3 id="第四条" tabindex="-1">第四条 <a class="header-anchor" href="#第四条" aria-label="Permalink to &quot;第四条&quot;">​</a></h3><p>四条有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。 公司股东对公司依法享有资产收益、参与重大决策和选择管理者等权利。</p><h3 id="第五条" tabindex="-1">第五条 <a class="header-anchor" href="#第五条" aria-label="Permalink to &quot;第五条&quot;">​</a></h3><p>五条设立公司应当依法制定公司章程。公司章程对公司、股东、董事、监事、高级管理人员具有约束力。</p><h3 id="第六条" tabindex="-1">第六条 <a class="header-anchor" href="#第六条" aria-label="Permalink to &quot;第六条&quot;">​</a></h3><p>六条公司应当有自己的名称。公司名称应当符合国家有关规定。 公司的名称权受法律保护。</p><h3 id="第七条" tabindex="-1">第七条 <a class="header-anchor" href="#第七条" aria-label="Permalink to &quot;第七条&quot;">​</a></h3><p>七条依照本法设立的有限责任公司，应当在公司名称中标明有限责任公司或者有限公司字样。 依照本法设立的股份有限公司，应当在公司名称中标明股份有限公司或者股份公司字样。</p><h3 id="第八条" tabindex="-1">第八条 <a class="header-anchor" href="#第八条" aria-label="Permalink to &quot;第八条&quot;">​</a></h3><p>八条公司以其主要办事机构所在地为住所。</p><h3 id="第九条" tabindex="-1">第九条 <a class="header-anchor" href="#第九条" aria-label="Permalink to &quot;第九条&quot;">​</a></h3><p>九条公司的经营范围由公司章程规定。公司可以修改公司章程，变更经营范围。 公司的经营范围中属于法律、行政法规规定须经批准的项目，应当依法经过批准。</p><h3 id="第十条" tabindex="-1">第十条 <a class="header-anchor" href="#第十条" aria-label="Permalink to &quot;第十条&quot;">​</a></h3><p>十条公司的法定代表人按照公司章程的规定，由代表公司执行公司事务的董事或者经理担任。 担任法定代表人的董事或者经理辞任的，视为同时辞去法定代表人。 法定代表人辞任的，公司应当在法定代表人辞任之日起三十日内确定新的法定代表人。</p><h3 id="第十一条" tabindex="-1">第十一条 <a class="header-anchor" href="#第十一条" aria-label="Permalink to &quot;第十一条&quot;">​</a></h3><p>一条法定代表人以公司名义从事的民事活动，其法律后果由公司承受。 公司章程或者股东会对法定代表人职权的限制，不得对抗善意相对人。 法定代表人因执行职务造成他人损害的，由公司承担民事责任。公司承担民事责任后，依照法律或者公司章程的规定，可以向有过错的法定代表人追偿。</p><h3 id="第十二条" tabindex="-1">第十二条 <a class="header-anchor" href="#第十二条" aria-label="Permalink to &quot;第十二条&quot;">​</a></h3><p>二条有限责任公司变更为股份有限公司，应当符合本法规定的股份有限公司的条件。股份有限公司变更为有限责任公司，应当符合本法规定的有限责任公司的条件。 有限责任公司变更为股份有限公司的，或者股份有限公司变更为有限责任公司的，公司变更前的债权、债务由变更后的公司承继。</p><h3 id="第十三条" tabindex="-1">第十三条 <a class="header-anchor" href="#第十三条" aria-label="Permalink to &quot;第十三条&quot;">​</a></h3><p>三条公司可以设立子公司。子公司具有法人资格，依法独立承担民事责任。 公司可以设立分公司。分公司不具有法人资格，其民事责任由公司承担。</p><h3 id="第十四条" tabindex="-1">第十四条 <a class="header-anchor" href="#第十四条" aria-label="Permalink to &quot;第十四条&quot;">​</a></h3><p>四条公司可以向其他企业投资。 法律规定公司不得成为对所投资企业的债务承担连带责任的出资人的，从其规定。</p><h3 id="第十五条" tabindex="-1">第十五条 <a class="header-anchor" href="#第十五条" aria-label="Permalink to &quot;第十五条&quot;">​</a></h3><p>五条公司向其他企业投资或者为他人提供担保，按照公司章程的规定，由董事会或者股东会决议；公司章程对投资或者担保的总额及单项投资或者担保的数额有限额规定的，不得超过规定的限额。 公司为公司股东或者实际控制人提供担保的，应当经股东会决议。 前款规定的股东或者受前款规定的实际控制人支配的股东，不得参加前款规定事项的表决。该项表决由出席会议的其他股东所持表决权的过半数通过。</p><h3 id="第十六条" tabindex="-1">第十六条 <a class="header-anchor" href="#第十六条" aria-label="Permalink to &quot;第十六条&quot;">​</a></h3><p>六条公司应当保护职工的合法权益，依法与职工签订劳动合同，参加社会保险，加强劳动保护，实现安全生产。 公司应当采用多种形式，加强公司职工的职业教育和岗位培训，提高职工素质。</p><h3 id="第十七条" tabindex="-1">第十七条 <a class="header-anchor" href="#第十七条" aria-label="Permalink to &quot;第十七条&quot;">​</a></h3><p>七条公司职工依照《中华人民共和国工会法》组织工会，开展工会活动，维护职工合法权益。公司应当为本公司工会提供必要的活动条件。公司工会代表职工就职工的劳动报酬、工作时间、休息休假、劳动安全卫生和保险福利等事项依法与公司签订集体合同。 公司依照宪法和有关法律的规定，建立健全以职工代表大会为基本形式的民主管理制度，通过职工代表大会或者其他形式，实行民主管理。 公司研究决定改制、解散、申请破产以及经营方面的重大问题、制定重要的规章制度时，应当听取公司工会的意见，并通过职工代表大会或者其他形式听取职工的意见和建议。</p><h3 id="第十八条" tabindex="-1">第十八条 <a class="header-anchor" href="#第十八条" aria-label="Permalink to &quot;第十八条&quot;">​</a></h3><p>八条在公司中，根据中国共产党章程的规定，设立中国共产党的组织，开展党的活动。公司应当为党组织的活动提供必要条件。</p><h3 id="第十九条" tabindex="-1">第十九条 <a class="header-anchor" href="#第十九条" aria-label="Permalink to &quot;第十九条&quot;">​</a></h3><p>九条公司从事经营活动，应当遵守法律法规，遵守社会公德、商业道德，诚实守信，接受政府和社会公众的监督。</p><h3 id="第二十条" tabindex="-1">第二十条 <a class="header-anchor" href="#第二十条" aria-label="Permalink to &quot;第二十条&quot;">​</a></h3><p>十条公司从事经营活动，应当充分考虑公司职工、消费者等利益相关者的利益以及生态环境保护等社会公共利益，承担社会责任。 国家鼓励公司参与社会公益活动，公布社会责任报告。</p><h3 id="第二十一条" tabindex="-1">第二十一条 <a class="header-anchor" href="#第二十一条" aria-label="Permalink to &quot;第二十一条&quot;">​</a></h3><p>一条公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益。 公司股东滥用股东权利给公司或者其他股东造成损失的，应当承担赔偿责任。</p><h3 id="第二十二条" tabindex="-1">第二十二条 <a class="header-anchor" href="#第二十二条" aria-label="Permalink to &quot;第二十二条&quot;">​</a></h3><p>二条公司的控股股东、实际控制人、董事、监事、高级管理人员不得利用关联关系损害公司利益。 违反前款规定，给公司造成损失的，应当承担赔偿责任。</p><h3 id="第二十三条" tabindex="-1">第二十三条 <a class="header-anchor" href="#第二十三条" aria-label="Permalink to &quot;第二十三条&quot;">​</a></h3><p>三条公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任。 股东利用其控制的两个以上公司实施前款规定行为的，各公司应当对任一公司的债务承担连带责任。 只有一个股东的公司，股东不能证明公司财产独立于股东自己的财产的，应当对公司债务承担连带责任。</p><h3 id="第二十四条" tabindex="-1">第二十四条 <a class="header-anchor" href="#第二十四条" aria-label="Permalink to &quot;第二十四条&quot;">​</a></h3><p>四条公司股东会、董事会、监事会召开会议和表决可以采用电子通信方式，公司章程另有规定的除外。</p><h3 id="第二十五条" tabindex="-1">第二十五条 <a class="header-anchor" href="#第二十五条" aria-label="Permalink to &quot;第二十五条&quot;">​</a></h3><p>五条公司股东会、董事会的决议内容违反法律、行政法规的无效。</p><h3 id="第二十六条" tabindex="-1">第二十六条 <a class="header-anchor" href="#第二十六条" aria-label="Permalink to &quot;第二十六条&quot;">​</a></h3><p>六条公司股东会、董事会的会议召集程序、表决方式违反法律、行政法规或者公司章程，或者决议内容违反公司章程的，股东自决议作出之日起六十日内，可以请求人民法院撤销。但是，股东会、董事会的会议召集程序或者表决方式仅有轻微瑕疵，对决议未产生实质影响的除外。 未被通知参加股东会会议的股东自知道或者应当知道股东会决议作出之日起六十日内，可以请求人民法院撤销；自决议作出之日起一年内没有行使撤销权的，撤销权消灭。</p><h3 id="第二十七条" tabindex="-1">第二十七条 <a class="header-anchor" href="#第二十七条" aria-label="Permalink to &quot;第二十七条&quot;">​</a></h3><p>七条有下列情形之一的，公司股东会、董事会的决议不成立： （一）未召开股东会、董事会会议作出决议； （二）股东会、董事会会议未对决议事项进行表决； （三）出席会议的人数或者所持表决权数未达到本法或者公司章程规定的人数或者所持表决权数； （四）同意决议事项的人数或者所持表决权数未达到本法或者公司章程规定的人数或者所持表决权数。</p><h3 id="第二十八条" tabindex="-1">第二十八条 <a class="header-anchor" href="#第二十八条" aria-label="Permalink to &quot;第二十八条&quot;">​</a></h3><p>八条公司股东会、董事会决议被人民法院宣告无效、撤销或者确认不成立的，公司应当向公司登记机关申请撤销根据该决议已办理的登记。 股东会、董事会决议被人民法院宣告无效、撤销或者确认不成立的，公司根据该决议与善意相对人形成的民事法律关系不受影响。</p><hr><p class="law-foot">本篇依据《中华人民共和国公司法》2023 年 12 月 29 日第十四届全国人大常委会第七次会议第二次修订文本，自 2024 年 7 月 1 日起施行；本站同步于 2026-11-07。</p>',59)])])}const b=e(o,[["render",i]]);export{u as __pageData,b as default};
